namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be in format XX000000 (2 letters followed by 6 digits).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures & Algorithms", CourseCode = "CS201", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has contributed to open-source compiler projects.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Title = "Operating Systems", CourseCode = "CS301", Description = "Concepts of process management, memory management, file systems, and concurrency in modern operating systems.", Credits = 4, Schedule = "Mon/Wed 1:00–2:30 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at a major tech company on kernel development before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", CourseCode = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. Robert Klein", InstructorBio = "Prof. Klein is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH202", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on computational linear algebra and its applications in machine learning.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, Title = "Classical Mechanics", CourseCode = "PHYS201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and rigid body dynamics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster has published extensively on theoretical mechanics and teaches with a focus on physical intuition.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 7, Title = "Electromagnetism", CourseCode = "PHYS301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma is a former research physicist who now brings real-world electromagnetic applications to the classroom.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG150", Description = "Workshop-based course focusing on fiction and poetry writing, peer critique, and revision techniques.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", InstructorName = "Prof. Diana Holt", InstructorBio = "Prof. Holt is a published novelist and poet who has mentored dozens of emerging writers.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, Title = "American Literature", CourseCode = "ENG220", Description = "Survey of major American literary works from the colonial period through the 21st century.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson specializes in 20th-century American fiction and has written two books on the Harlem Renaissance.", DepartmentId = 4, DepartmentName = "English", IsFeatured = true },
            new() { Id = 10, Title = "World History to 1500", CourseCode = "HIST101", Description = "A global survey of human civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Catherine Moore", InstructorBio = "Dr. Moore is an archaeologist and historian who has led excavations in the Mediterranean region.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 11, Title = "Modern European History", CourseCode = "HIST250", Description = "Europe from the Enlightenment to the present, covering revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", InstructorName = "Dr. Thomas Weber", InstructorBio = "Dr. Weber is a specialist in 20th-century European political history and a frequent media commentator.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

